-- Venue Live Guest "Aksi Mahasiswa". Aditif & idempoten. Jalankan SETELAH admin-live-event-aqiqah.sql (jenis acara aksimhs), admin-live-theme.sql, admin-live-decor.sql, admin-live-decor-avatars.sql, dan admin-live-decor-garden-layout.sql (skrip tata letak itu melewati venue ini karena ukuran/posisi dekornya diatur sendiri).
insert into public.live_venues (key, name, event_type, areas, max_guests, active, sort, bg_pos, nm_theme)
select 'aksimhs', 'Aksi Mahasiswa (forum & demonstrasi damai)', 'aksimhs', coalesce((select areas from public.live_venues where key = 'little-ballerina'), '[]'::jsonb), 300, false, 134, 'center 38%',
  $t${"name":"Aksi Mahasiswa","orn":"diamond","ui":{"ivory":"#FFF5F5","white":"#FFFFFF","soft":"#FAD9DC","soft2":"#E89AA3","accent":"#C8102E","deep":"#6B0A1A","ink":"#1F2A4D","mute":"#7B6A78","line":"#F2CDD1","serif":"\"Fredoka\",system-ui,sans-serif","sans":"Inter,system-ui,sans-serif","rad":18,"btnr":14,"btnt":"none","btnls":".02em"},"mono":{"font":"\"Fredoka\",system-ui,sans-serif","it":0,"paper":"#FFFAFA","ink":"#1F2A4D","accent":"#C8102E","gold":"#D9A21B","leaf":"#FAD9DC","hbg":"rgba(255,245,245,.94)","hline":"#E89AA3","motif":"diamond"},"hud":{"bg":"rgba(31,42,77,.9)","acc":"#FFFFFF","on":"#1F2A4D"},"scr":{"wine":"#6B0A1A","veil":"255,245,245"}}$t$::jsonb
where not exists (select 1 from public.live_venues where key = 'aksimhs');
